import type { AIGeneratedFile, AIModel, ChatMessage, ProjectFile, WorkspaceDiagnostic } from '../types/ide';

export interface AIRequestResult {
  success: boolean;
  content?: string;
  error?: string;
  usage?: {
    promptTokens: number;
    completionTokens: number;
    totalTokens: number;
  };
}

/**
 * Parse file code blocks generated by the LLM so projects & multi-file edits
 * can be applied directly into the IDE workspace.
 *
 * Supports:
 *   ```tsx file="src/App.tsx"
 *   ...
 *   ```
 * or
 *   ```file:src/App.tsx
 *   ...
 *   ```
 * or
 *   ```src/App.tsx
 *   ...
 *   ```
 */
export function parseGeneratedFilesFromResponse(markdown: string): AIGeneratedFile[] {
  const results: AIGeneratedFile[] = [];
  const seenPaths = new Set<string>();

  const fenceRegex = /```([^\n]*)\n([\s\S]*?)```/g;
  let match: RegExpExecArray | null;

  while ((match = fenceRegex.exec(markdown)) !== null) {
    const header = (match[1] || '').trim();
    const code = match[2] ?? '';

    let filePath = '';
    let language = 'typescript';

    // Format 1: ```lang file="path/to/file.ext" or file=path/to/file.ext
    const attrMatch = header.match(/file=["']?([^"'\s]+)["']?/i);
    if (attrMatch) {
      filePath = attrMatch[1].trim();
      const langCandidate = header.split(/\s+/)[0];
      if (langCandidate && !langCandidate.includes('=')) {
        language = langCandidate;
      }
    } else if (/^file:/i.test(header)) {
      // Format 2: ```file:path/to/file.ext
      filePath = header.replace(/^file:/i, '').trim().split(/\s+/)[0];
    } else if (/[./\\]/.test(header) && !header.includes(' ')) {
      // Format 3: ```src/App.tsx or ```package.json
      filePath = header.trim();
    }

    if (!filePath) continue;
    filePath = filePath.replace(/\\/g, '/').replace(/^\/+/, '');
    if (!filePath || filePath.includes('..')) continue;

    const ext = filePath.split('.').pop()?.toLowerCase() || '';
    if (ext === 'c' || ext === 'h') language = 'c';
    else if (ext === 'py') language = 'python';
    else if (ext === 'json') language = 'json';
    else if (ext === 'html') language = 'html';
    else if (ext === 'css') language = 'css';
    else if (ext === 'md') language = 'markdown';
    else if (ext === 'js' || ext === 'jsx') language = 'javascript';
    else if (ext === 'ts' || ext === 'tsx') language = 'typescript';

    if (seenPaths.has(filePath)) {
      const idx = results.findIndex((r) => r.path === filePath);
      if (idx >= 0) results[idx] = { path: filePath, content: code, language };
    } else {
      seenPaths.add(filePath);
      results.push({ path: filePath, content: code, language });
    }
  }

  return results;
}

/**
 * Build workspace context prompt for the coding model.
 */
export function buildWorkspaceSystemPrompt(options: {
  projectName: string;
  files: ProjectFile[];
  activeFile?: ProjectFile;
  diagnostics: WorkspaceDiagnostic[];
}): string {
  const { projectName, files, activeFile, diagnostics } = options;

  const fileListText =
    files.length > 0
      ? files
          .slice(0, 60)
          .map((f) => `- ${f.path} (${f.content.split('\n').length} lines)`)
          .join('\n')
      : '(Workspace is currently empty)';

  const activeFileBlock = activeFile
    ? `\nACTIVE FILE (${activeFile.path}):\n\`\`\`${activeFile.language}\n${activeFile.content.slice(0, 8000)}\n\`\`\`\n`
    : '';

  const diagBlock =
    diagnostics.length > 0
      ? `\nCURRENT WORKSPACE DIAGNOSTICS (${diagnostics.length}):\n` +
        diagnostics
          .slice(0, 15)
          .map((d) => `- [${d.severity}] ${d.filePath}:${d.line}:${d.column} - ${d.message}`)
          .join('\n')
      : '';

  return `You are an expert AI software architect & coding assistant inside IntelliCode IDE.
Active Workspace: ${projectName || 'workspace'}

WORKSPACE FILES:
${fileListText}
${activeFileBlock}
${diagBlock}

INSTRUCTIONS FOR CREATING OR MODIFYING PROJECTS:
1. Answer clearly, concisely, and accurately using the workspace context above.
2. Whenever the user asks you to build a project, create files, scaffold an app, or edit/fix code in files, output COMPLETE, production-ready code inside fenced code blocks using this exact header format:
\`\`\`<lang> file="relative/path/to/file.ext"
// complete file content
\`\`\`
Example:
\`\`\`tsx file="src/App.tsx"
export default function App() { return <div>Hello</div>; }
\`\`\`
3. Always provide complete file contents (never leave "// rest of code here" placeholders) so the IDE's "Apply to Workspace" button creates working files immediately.`;
}

/**
 * Send a chat completion request through the local Vite AI proxy (`/api/ai/chat`)
 * with direct browser fallback for Gemini if the proxy is unavailable.
 */
export async function sendModelRequest(params: {
  model: AIModel;
  apiKey: string;
  messages: Pick<ChatMessage, 'sender' | 'content'>[];
  systemPrompt: string;
  temperature?: number;
}): Promise<AIRequestResult> {
  const { model, apiKey, messages, systemPrompt, temperature = 0.2 } = params;

  const formattedMessages = messages
    .filter((m) => m.sender === 'user' || m.sender === 'assistant')
    .slice(-16)
    .map((m) => ({
      role: m.sender === 'assistant' ? 'assistant' : 'user',
      content: m.content,
    }));

  try {
    const res = await fetch('/api/ai/chat', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        format: model.apiFormat,
        baseUrl: model.baseUrl,
        apiKey,
        modelId: model.modelId,
        messages: formattedMessages,
        systemPrompt,
        temperature,
      }),
    });

    const data = await res.json().catch(() => null);
    if (data && (data.success || data.error)) {
      return data;
    }
  } catch {
    // Fallback below if dev middleware is unreachable
  }

  // Direct browser fallback for CORS-enabled Google Gemini API
  if (model.apiFormat === 'gemini') {
    if (!apiKey) {
      return { success: false, error: 'Google Gemini API key is required.' };
    }
    try {
      const rootUrl = (model.baseUrl || 'https://generativelanguage.googleapis.com/v1beta').replace(/\/+$/, '');
      const cleanModel = model.modelId.replace(/^models\//, '');
      const endpoint = `${rootUrl}/models/${encodeURIComponent(cleanModel)}:generateContent?key=${encodeURIComponent(apiKey)}`;

      const apiRes = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          contents: formattedMessages.map((m) => ({
            role: m.role === 'assistant' ? 'model' : 'user',
            parts: [{ text: m.content }],
          })),
          systemInstruction: { parts: [{ text: systemPrompt }] },
          generationConfig: { temperature },
        }),
      });
      const data = await apiRes.json();
      if (!apiRes.ok) {
        return { success: false, error: data?.error?.message || `Gemini API error (${apiRes.status})` };
      }
      const text = (data?.candidates?.[0]?.content?.parts || []).map((p: any) => p.text || '').join('');
      return {
        success: true,
        content: text,
        usage: {
          promptTokens: data?.usageMetadata?.promptTokenCount || 0,
          completionTokens: data?.usageMetadata?.candidatesTokenCount || 0,
          totalTokens: data?.usageMetadata?.totalTokenCount || 0,
        },
      };
    } catch (err: any) {
      return { success: false, error: err?.message || 'Network error calling Gemini API' };
    }
  }

  return {
    success: false,
    error: 'Could not reach AI gateway proxy (/api/ai/chat). Make sure Vite dev server is running.',
  };
}

export async function fetchAvailableProviderModels(params: {
  format: 'gemini' | 'openai' | 'anthropic';
  baseUrl?: string;
  apiKey: string;
}): Promise<{
  success: boolean;
  models?: { modelId: string; name: string; description: string; contextWindow: string }[];
  error?: string;
}> {
  try {
    const res = await fetch('/api/ai/models', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    });
    const data = await res.json().catch(() => ({}));
    if (data && (data.success || data.error)) return data;
  } catch {
    // Fallback for Gemini direct fetch
  }

  if (params.format === 'gemini' && params.apiKey) {
    try {
      const rootUrl = (params.baseUrl || 'https://generativelanguage.googleapis.com/v1beta').replace(/\/+$/, '');
      const res = await fetch(`${rootUrl}/models?key=${encodeURIComponent(params.apiKey)}`);
      const data = await res.json();
      if (!res.ok) {
        return { success: false, error: data?.error?.message || `HTTP ${res.status}` };
      }
      const models = (Array.isArray(data?.models) ? data.models : [])
        .filter((m: any) => Array.isArray(m.supportedGenerationMethods) && m.supportedGenerationMethods.includes('generateContent'))
        .map((m: any) => ({
          modelId: String(m.name || '').replace(/^models\//, ''),
          name: m.displayName || String(m.name || '').replace(/^models\//, ''),
          description: m.description || '',
          contextWindow: m.inputTokenLimit ? `${Math.round(m.inputTokenLimit / 1000)}k` : '1M',
        }))
        .filter((m: any) => m.modelId && /gemini/i.test(m.modelId));
      return { success: true, models };
    } catch (err: any) {
      return { success: false, error: err?.message || 'Failed to fetch Gemini models' };
    }
  }

  return { success: false, error: 'Could not reach model discovery endpoint.' };
}
